// Generate input: start with arbitrary string bytes and clamp size for performance
std::string in = FUZZ_PARAM_STR();
if (in.size() > 1024) { in.resize(1024); }

// Optionally coerce input toward a plausible Base64 alphabet to exercise success paths
unsigned int mode = *FUZZ_PARAM(unsigned int);
bool make_b64_like = (mode & 1u) != 0u;
if (make_b64_like) {
    static const char *alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    for (size_t i = 0; i < in.size(); ++i) {
        // Map arbitrary bytes to canonical Base64 characters
        unsigned char idx = static_cast<unsigned char>(in[i]) & 0x3F; // 0..63
        in[i] = alphabet[idx];
    }
    // With 50% probability, pad to a multiple of 4 using '=' to increase chance of valid decoding
    if (((mode >> 1) & 1u) != 0u) {
        size_t rem = in.size() % 4u;
        if (rem != 0u) {
            size_t pad = 4u - rem; // at most 3
            if (in.size() + pad > 1024) { pad = (in.size() + pad > 1024) ? (1024 - in.size()) : pad; }
            in.append(pad, '=');
        }
    }
}

// Enforce NONNULL requirements
size_t inlen = in.size();
size_t outlen = 0;
unsigned char *decoded = base64_dec(in.c_str(), inlen, &outlen);

// Return may be NULL on allocation/decoding failure; treat as a valid outcome and bail without outputs
if (!decoded) { FUZZ_BAIL(); }

// Do not assume NUL-termination; use outlen only. Optionally touch a couple bytes to cover paths.
if (outlen > 0) { volatile unsigned char t = decoded[0]; (void)t; }
if (outlen > 1) { volatile unsigned char t2 = decoded[outlen - 1]; (void)t2; }

// Free the MALLOC-allocated result as required by the API contract
free(decoded);

